            setTo(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-form-submit">Add period</button>
        {add.isError && <span data-testid="period-form-error" role="alert"> Could not add the period: it needs a name not already on the sheet and a from-date on or before its to-date (YYYY-MM-DD), not overlapping another period.</span>}
      </form>
      <form
        data-testid="period-generate-form"
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            generate.reset();
            return generate.mutateAsync({ from: genFrom.trim(), to: genTo.trim() });
          });
        }}
      >
        <input
          data-testid="period-generate-from"
          value={genFrom}
          placeholder="From (YYYY-MM-DD)"
          onChange={(e) => {
            setGenFrom(e.target.value);
            generate.reset();
          }}
        />{' '}
        <input
          data-testid="period-generate-to"
          value={genTo}
          placeholder="To (YYYY-MM-DD)"
          onChange={(e) => {
            setGenTo(e.target.value);
            generate.reset();
          }}
        />{' '}
        <button type="submit" data-testid="period-generate">Generate monthly periods</button>
        {generate.isSuccess && (
          <>
            {' '}
            Made <span data-testid="period-generated">{generate.data.generated}</span>
          </>
        )}
        {generate.isError && (
          <span data-testid="period-generate-error" role="alert">
            {' '}
            Could not generate periods: the to-date must be on or after the from-date (YYYY-MM-DD).
          </span>
        )}
      </form>
    </>
  );
}
import { countsAtEnd, useClaims } from '../claims/useClaims';
import { gradeOn, heldOn, usePeople } from '../people/usePeople';
import { claimDue, toCents } from '../rates/due';
import { rateOn, useRates } from '../rates/useRates';
import { useFloor, useLatePct, usePolicyDate } from '../settings/useSettings';
import { useSheetToday } from '../sheet/useSheetToday';
import { periodOf, usePeriods, type Period } from './usePeriods';

/** A person's due-total for a period: the dues as shown now, late charges included, of their claims whose date
 *  falls in it that counted at the end of its last day (see countsAtEnd), leaving out their unbound OPEN claims dated within one of their holds (a claim whose due is n/a
 *  adds nothing); a closed period gives the figure fixed when it was closed (0.00 for a person added later). */
export function usePersonPeriodDueTotal(sheet: string): (period: Period, personId: string) => bigint {
  const periods = usePeriods(sheet);
  const people = usePeople(sheet);
  const claims = useClaims(sheet);
  const rates = useRates(sheet);
  const floor = useFloor(sheet);
  const late = { pct: useLatePct(sheet), today: useSheetToday(sheet) };
  const policy = usePolicyDate(sheet);
  const personOf = new Map(people.map((p) => [p.id, p]));
  return (period: Period, personId: string) => {
    if (period.closed) return toCents(period.closedPersonTotals[personId] ?? '0.00');
    const person = personOf.get(personId);
    if (!person) return 0n;
    return claims
      .filter((c) => c.personId === personId && countsAtEnd(c, period.to, (date) => heldOn(person, date), late.today) && periodOf(periods, c.date)?.name === period.name)
      .reduce((sum, c) => sum + (claimDue(c, rateOn(rates, gradeOn(person, c.date), c.date), floor, late, policy) ?? 0n), 0n);
  };
}

/** A period's due-total: the sum of every person's due-total for it. */
export function usePeriodDueTotal(sheet: string): (period: Period) => bigint {
  const people = usePeople(sheet);
  const personDueTotal = usePersonPeriodDueTotal(sheet);
  return (period: Period) => people.reduce((sum, p) => sum + personDueTotal(period, p.id), 0n);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A period: a name unique on the sheet, from and to dates (YYYY-MM-DD, both inclusive), whether it
 *  is closed, the due-total fixed when it was closed ("" while open), and each person's due-total for
 *  it fixed then, by person id (empty while open; a person added later has none). */
export type Period = {
  name: string;
  from: string;
  to: string;
  closed: boolean;
  closedTotal: string;
  closedPersonTotals: Record<string, string>;
};

export const periodsKey = (sheet: string) => ['sheet', sheet, 'periods'] as const;

/** The sheet's periods, by from-date. */
export function usePeriods(sheet: string): Period[] {
  const { data } = useQuery({
    queryKey: periodsKey(sheet),
    queryFn: () => getJson<Period[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`),
    enabled: sheet !== '',
  });
  return data ?? [];
}

/** The period whose dates contain a date; periods never overlap, so there is at most one. */
export function periodOf(periods: Period[], date: string): Period | undefined {
  return periods.find((p) => p.from <= date && date <= p.to);
}

